using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // --- Stock Level Tests ---

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        int level = _tracker.GetStockLevel("UNKNOWN-SKU");
        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void AddStock_NewSku_SetsStockLevel()
    {
        _tracker.AddStock("SKU-001", 50);
        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_IncrementsStockLevel()
    {
        _tracker.AddStock("SKU-001", 30);
        _tracker.AddStock("SKU-001", 20);
        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_MultipleSkus_TracksIndependently()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-B", 25);

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_NegativeQuantity_ThrowsArgumentException()
    {
        _tracker.AddStock("SKU-001", -5);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_ZeroQuantity_ThrowsArgumentException()
    {
        _tracker.AddStock("SKU-001", 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_NullSku_ThrowsArgumentException()
    {
        _tracker.AddStock(null!, 10);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_EmptySku_ThrowsArgumentException()
    {
        _tracker.AddStock("", 10);
    }

    // --- Reorder Alert Tests ---

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-001", 2);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-001", 100);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_ZeroStock_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("EMPTY-SKU"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("NEVER-ADDED"));
    }

    // --- Warehouse Transfer Tests (placeholders for future implementation) ---

    // Uncomment and adjust once a Transfer method is added to InventoryTracker.
    // Expected signature: void Transfer(string sku, int quantity, string fromWarehouse, string toWarehouse)

